      if(e.id==='flip'){this.flip=Math.min(1,k/.75)*Math.PI*2;tgt.l0=tgt.l1=-1.2;tgt.k0=tgt.k1=1.6;tgt.a0z=-.4;tgt.a1z=.4;tgt.a0x=tgt.a1x=-1;if(k>.8){this.emote=null;this.flip=0;}}
