  const w2s=(wx,wz)=>{const dx=wx-p.x,dz=wz-p.z;return [h+(dx*rx+dz*rz)*k,h-(dx*fx+dz*fz)*k];};
  const x=miniX;x.save();drawWorld(x,w2s,k,S);
