    x.font=`700 ${Math.round(S*.03)}px system-ui,-apple-system,sans-serif`;const t=zLabel(z),tw=x.measureText(t).width,ty=py+S*.042;px=Math.min(S*.95-tw/2-8,Math.max(S*.05+tw/2+8,px));
