  x.fillStyle='#8e6cff';x.beginPath();x.roundRect?x.roundRect(px-yw/2,yy-S*.024,yw,S*.048,S*.024):x.rect(px-yw/2,yy-S*.024,yw,S*.048);x.fill();x.lineWidth=3;x.strokeStyle='#fff';x.stroke();
